    // Connect Islands with dash-lines via SVG overlay
    function renderShippingLanes() {
      const lanes = document.getElementById(&quot;shipping-lanes&quot;);
      lanes.innerHTML = &quot;&quot;;

      // Draw routes between Core and surrounding port islands
      const core = state.islands[0];
      const gameMatrix = document.getElementById(&quot;game-matrix&quot;);
      const size = gameMatrix.offsetWidth;
      const step = size / 10;

      state.islands.forEach((island, idx) =&gt; {
        if (idx !== 0) {
          const x1 = core.col * step + step / 2;
          const y1 = core.row * step + step / 2;
