        renderBoard();
      }
    }

    // Draw single Card from game Deck
    function drawCard() {
      if (state.hand.length &gt;= 4) return;
      const randIdx = Math.floor(Math.random() * cardLibrary.length);
      const cardRef = cardLibrary[randIdx];
      // Clone card with unique ID
      const cardInst = { ...cardRef, id: Date.now() + Math.random() };
      state.hand.push(cardInst);
    }

    // Select Card from hand to cast
    function selectCard(cardId) {
      if (state.selectedCardId === cardId) {
        state.selectedCardId = null; // Deselect
      } else {
        const card = state.hand.find(c =&gt; c.id === cardId);
        if (state.attention &lt; card.cost) {
          showModal(&quot;⚠️ Limit Triggered&quot;, &quot;You do not possess enough Sovereign Attention to execute this nudge card.&quot;, &quot;❌&quot;);
          return;
