    // Casting Actions on Islands
    function applyCardAction(cardInstId, islandId) {
      const cardIdx = state.hand.findIndex(c =&gt; c.id === cardInstId);
      if (cardIdx === -1) return;

      const card = state.hand[cardIdx];
      const island = state.islands.find(i =&gt; i.id === islandId);

      if (!island) return;

      // Consume attention cost
      state.attention -= card.cost;

      // Apply specific behavior modifiers
      switch (card.action) {
        case &quot;speed&quot;:
          island.focus = &quot;Exploration&quot;;
          island.scaffolding += 6;
          // Spawn Icebreaker boat
          state.boats.push({
            id: Date.now(),
            type: &quot;icebreaker&quot;,
            islandId: island.id,
            col: island.col,
