          });
          logChronicle(
            `Nudge applied: ${island.name} Strategy speed shifted.`,
            `Lighthouse beamed Exothermic guidance. Core active worker pool expanded with fresh Icebreaker. Scaffolding has scaled but exploration is running at maximum velocity.`
          );
          break;

        case &quot;prune&quot;:
          island.focus = &quot;Pruning&quot;;
          if (island.scaffolding &gt; 2) {
            const cut = Math.floor(island.scaffolding / 2);
            island.scaffolding -= cut;
            island.crystallized += Math.max(1, Math.floor(cut / 3));
            logChronicle(
              `Wise Prune Pass at ${island.name}.`,
              `The Dredgers have sheared away unneeded scaffolding modules. Composting has completed, yielding solid crystalline logic.`
            );
          } else {
            logChronicle(
              `Prune aborted.`,
              `No messy scaffolding available on the ${island.name} code platform to slice.`
            );
          }
          break;

        case &quot;pivot&quot;:
          // Flush-freeze / Liquidate
          island.focus = &quot;Idle&quot;;
          const boatsToKill = state.boats.filter(b =&gt; b.islandId === island.id);
          state.boats = state.boats.filter(b =&gt; b.islandId !== island.id);

          // Compost logic
          const refundedSunlight = boatsToKill.length * 35;
          state.sunlight += refundedSunlight;
          island.scaffolding = 0;

          logChronicle(
            `FLASH FREEZE triggered for ${island.name}.`,
            `Sovereign operator executed SIGKILL termination. All active local worker boats liquidated instantly. Composted logic recovered +${refundedSunlight} Sunlight. Technical debt avoided completely.`
          );
          break;

        case &quot;crystallize&quot;:
          island.focus = &quot;Integration&quot;;
          island.progress = Math.min(100, island.progress + 15);
          logChronicle(
            `Crystallization Protocol deployed.`,
            `The Tugboat fleet anchored solid code primitives into the main line of ${island.name}. Module stability increased +15%.`
          );
          break;
      }

      // Discard card and draw replacement
      state.hand.splice(cardIdx, 1);
      drawCard();
      calculateIntegration();
    }

    // Step Ecosystem Forward (End Turn / Week)
    function endTurn() {
      state.turn++;

      // Recharge attention points
      state.attention = state.maxAttention;

      // System execution simulations for every active sector
      let weeklySunlightBurn = 0;
      let totalScaffoldingAccumulated = 0;

      state.boats.forEach(boat =&gt; {
        // Simple randomized travel step
        const stepDir = Math.random() &gt; 0.5 ? 1 : -1;
        if (Math.random() &gt; 0.5) {
          boat.col = Math.min(9, Math.max(0, boat.col + stepDir));
        } else {
          boat.row = Math.min(9, Math.max(0, boat.row + stepDir));
        }

        // Sunlight (API Token) burn rate per active boat type
        if (boat.type === &quot;icebreaker&quot;) {
          weeklySunlightBurn += 15;
        } else if (boat.type === &quot;dredger&quot;) {
          weeklySunlightBurn += 10;
        } else {
          weeklySunlightBurn += 5;
        }
      });

      // Update islands progress based on focus modes
      state.islands.forEach(island =&gt; {
        if (island.focus === &quot;Exploration&quot;) {
          island.scaffolding += 2;
          island.progress = Math.min(100, island.progress + 3);
          weeklySunlightBurn += 10; // Extra sector run cost
        } else if (island.focus === &quot;Pruning&quot;) {
          if (island.scaffolding &gt; 0) {
            island.scaffolding = Math.max(0, island.scaffolding - 2);
            island.crystallized++;
