        totalScaffoldingAccumulated += island.scaffolding;
      });

      // Consume Sunlight
      state.sunlight = Math.max(0, state.sunlight - weeklySunlightBurn);

      // Decay / Chaos shifts based on raw scaffolding (technical debt)
      const debtImpact = Math.floor(totalScaffoldingAccumulated * 0.8);
      state.decay = Math.min(100, Math.max(5, state.decay + (debtImpact - 4)));

      // Auto-Narrator writes the weekly report story
      generateWeeklyStory(weeklySunlightBurn, totalScaffoldingAccumulated);

      // Check win/loss parameters
      checkGameLimits();

      // Refresh visuals
      calculateIntegration();
      updateUI();
      renderBoard();
